{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": [
    "C01","C02","C03","C04","C06","C07","C08","C09","C10","C11","C12","C13","C14","C15","C16","C17","C19","C20","C21","C22","C24"
  ],
  "contradictory_card_ids": ["C23"],
  "prediction_basis_card_ids": [
    "C01","C02","C03","C04","C06","C07","C08","C09","C10","C11","C12","C13","C14","C15","C16","C17","C19","C20","C21","C22","C24"
  ],
  "claims": [
    {
      "claim": "All quantified oral bioavailability records in the visible gold contexts are at or above 35% (safinamide ~95% fasted/fed; GSK1322322 77% fed; encainide 52–78% in cirrhosis; vernakalant 58–71% fasted; ketanserin 49–60% fasted; haloperidol 35% fasted; ebastine ~40%; ONO-4641 0.71), and none affirmatively supports F < 20%.",
      "card_ids": ["C01","C02","C03","C04","C06","C07","C08","C09","C10","C11","C12","C13","C14","C15","C16","C17","C21","C22"]
    },
    {
      "claim": "L2 context records reinforce high-F transfer: safinamide 95% with no significant first-pass effect (C19, C20), ONO-4641 monkey absolute F = 0.71 (C17), and encainide 78% in EM cirrhosis and 52% in PM cirrhosis (C21, C22).",
      "card_ids": ["C17","C19","C20","C21","C22"]
    },
    {
      "claim": "The only contradictory card, C23, is an unquantified qualitative 'low' for ebastine that conflicts with C02 (~40%) and C18 ('highly bioavailable') and does not provide affirmative threshold-relevant evidence of F < 20%.",
      "card_ids": ["C02","C18","C23"]
    },
    {
      "claim": "L3 oral exposure records show measurable oral AUC/Cmax for several reference molecules; the most structurally relevant is C24 for mosapride (M07), a close 4-amino-5-chloro-2-alkoxybenzamide analog of the query, with AUC0-t 84.3 ng·h/ml after 5 mg oral, supporting oral absorption/exposure, though without an IV comparator it does not quantify F.",
      "card_ids": ["C24"]
    },
    {
      "claim": "The remaining L3 records (C25–C35) are exposure values for less query-similar molecules; C29/C33 and C27/C35 are duplicate study entries, and C26 is only a tmax. They provide general oral-exposure context but are not direct F evidence.",
      "card_ids": ["C25","C26","C27","C28","C29","C30","C31","C32","C33","C34","C35"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C24","C25","C26","C27","C28","C29","C30","C31","C32","C33","C34","C35"]
    }
  ],
  "evidence_gaps": [
    "No direct same-molecule absolute oral bioavailability record for the query; decision relies on structural transfer from related contexts.",
    "C24 (mosapride analog) provides oral AUC but no IV comparator, so it cannot quantify F or directly confirm F >= 20%.",
    "No query-specific solubility, permeability, first-pass extraction, or clearance data; partial ionization at pH 7.4 and 9 rotatable bonds remain unresolved absorption uncertainties.",
    "The ebastine context is internally inconsistent (C02 ~40%, C18 'highly bioavailable', C23 'low'), and C22 is n=1, limiting precision.",
    "Most L3 exposure records are for structurally dissimilar molecules and are not independent votes."
  ],
  "decision_summary": "L3 adds measurable oral exposure records, most notably C24 for the close mosapride analog, but no direct F value or contradictory threshold evidence. The prior high prediction is retained and modestly strengthened; confidence remains moderate because F is inferred by transfer rather than measured for the query."
}

